/// Semantic colors for Ferry. Each one reads the right hex value for the
/// current light or dark appearance, so a view never types a hex value.
enum FerryColor {
    /// Turns a "#rrggbb" string into an NSColor.
    private static func nsColor(hex: String) -> NSColor {
        var hexString = hex
        if hexString.hasPrefix("#") {
            hexString.removeFirst()
        }
        var rgbValue: UInt64 = 0
        Scanner(string: hexString).scanHexInt64(&rgbValue)
        let red = CGFloat((rgbValue & 0xFF0000) >> 16) / 255.0
        let green = CGFloat((rgbValue & 0x00FF00) >> 8) / 255.0
        let blue = CGFloat(rgbValue & 0x0000FF) / 255.0
        return NSColor(srgbRed: red, green: green, blue: blue, alpha: 1.0)
    }

    /// Builds a Color with a dynamic provider, so it picks the light or dark
    /// hex value on its own, each time the appearance is resolved.
    private static func role(_ light: String, _ dark: String) -> Color {
        let dynamic = NSColor(name: nil) { appearance in
            let isDark = appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
            return isDark ? nsColor(hex: dark) : nsColor(hex: light)
        }
        return Color(nsColor: dynamic)
    }

    static let background = role("#fcfcfd", "#111113")
    static let surface = role("#f9f9fb", "#19191b")
    static let surfaceRaised = role("#eff0f3", "#222325")
    static let border = role("#d8d9e0", "#393a40")
    static let borderStrong = role("#b9bbc6", "#5f606a")
